const drawer=document.querySelector('#chatDrawer');const backdrop=document.querySelector('#chatBackdrop');const messages=document.querySelector('#messages');const input=document.querySelector('#chatInput');const preview=document.querySelector('#answerPreview');const toast=document.querySelector('#toast');const launcher=document.querySelector('.assistant-launcher');
const answers={referencePlan:{match:/reference|area|size|square|sq ft|2220|2,220|1410|1,410|810|floor plan/i,text:'The official brochure presents a 2,220 sq ft two-level reference villa, with 1,410 sq ft on the ground floor and 810 sq ft on the first floor.',tag:'OFFICIAL REFERENCE PLAN',title:'2,220 sq ft across two levels',detail:'Ground floor · 1,410 sq ft | First floor · 810 sq ft',image:'assets/brochure-ground-floor.jpg',source:'Official Glitz Pride brochure'},customise:{match:/custom|tailor|requirement|personal/i,text:'The current project feedback allows villas to be tailored around the owner’s space and lifestyle requirements. The official brochure separately presents a 2,220 sq ft reference plan; final alternatives require owner and design-team confirmation.',tag:'TAILORED VILLA DIRECTION',title:'Designed around you',detail:'Personalised requirements · final plan by consultation',image:'assets/brochure-villa.jpg',source:'Current project feedback; reference plan from official brochure'},family:{match:/family|five|children|kids/i,text:'The design direction can respond to a family’s preferred room arrangement and outdoor needs. The brochure’s official reference villa totals 2,220 sq ft across two levels.',tag:'FAMILY-LED PLANNING',title:'A home shaped for your family',detail:'Natural light · generous ventilation · indoor-outdoor connection',image:'assets/brochure-villas.jpg',source:'Official brochure and current project feedback'},amenities:{match:/amenit|club|garden|parking|health|security|surveillance|play|shuttle/i,text:'The official brochure lists a clubhouse, vegetable garden, wide guest parking, children’s play area, health club, shuttle court, high security standards and state-of-the-art surveillance systems.',tag:'BROCHURE-LISTED AMENITIES',title:'More than a home',detail:'Wellbeing · play · community · security',image:'assets/brochure-greenery.jpg',source:'Official Glitz Pride brochure'},location:{match:/location|near|thrissur|town|hospital|college|school|city|map|sobha|amala/i,text:'The brochure places Glitz Pride at Amala Nagar on Anugraha Road, adjacent to Peramangalam Police Station. It lists Amala Medical College at 1 km, Sobha City at 3 km and Thrissur City at 6 km.',tag:'OFFICIAL LOCATION GUIDE',title:'Connected to Thrissur',detail:'Amala Medical College · 1 km | Sobha City · 3 km | Thrissur City · 6 km',image:'assets/brochure-location-map.jpg',source:'Official Glitz Pride brochure'},designers:{match:/architect|designer|designed|lijo|reny/i,text:'The official brochure credits Lijo. Reny. Architects with the Glitz Pride design and highlights the studio’s balance of artistic appeal, experimentation, nature and practical planning.',tag:'PROJECT DESIGNERS',title:'Lijo. Reny. Architects',detail:'Architecture · artistic direction · practical balance',image:'assets/brochure-villas.jpg',source:'Official Glitz Pride brochure'},visit:{match:/visit|schedule|contact|call|book/i,text:'This private prototype does not submit enquiries. Current visit and booking contacts should be confirmed with the property owner before the production application is published.',tag:'DEMO ENQUIRY FLOW',title:'Plan a private visit',detail:'No information is collected or submitted in this concept demonstration.',image:'assets/brochure-entry.jpg',source:'Prototype interaction only',toast:true},default:{text:'I can explain the official reference villa plan, brochure-listed amenities, location distances, project designers and the current tailored-villa direction. Try asking about one of those topics.',tag:'BROCHURE GUIDE',title:'Let’s explore together',detail:'Choose a topic to see its matching visual summary and source.',image:'assets/brochure-villa.jpg',source:'Official Glitz Pride brochure'}};
function openChat(question){drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');backdrop.hidden=false;document.body.classList.add('chat-is-open');document.body.style.overflow='hidden';launcher.setAttribute('aria-expanded','true');setTimeout(()=>input.focus(),350);if(question)setTimeout(()=>respond(question),200)}function closeChat(){drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');backdrop.hidden=true;document.body.classList.remove('chat-is-open');document.body.style.overflow='';launcher.setAttribute('aria-expanded','false');launcher.focus()}function selectAnswer(q){return Object.values(answers).find(a=>a.match&&a.match.test(q))||answers.default}function respond(q){if(!q.trim())return;messages.insertAdjacentHTML('beforeend',`<div class="message user"><p>${escapeHtml(q)}</p></div>`);const a=selectAnswer(q);setTimeout(()=>{messages.insertAdjacentHTML('beforeend',`<div class="message assistant"><span>GP</span><p>${a.text}</p></div>`);messages.scrollTop=messages.scrollHeight;preview.innerHTML=`<div class="preview-image" style="background-image:url('${a.image}')"><span>LIVE PREVIEW</span></div><div class="preview-content"><small>${a.tag}</small><h3>${a.title}</h3><p>${a.detail}</p><div class="preview-source">Reference · ${a.source}</div></div>`;if(a.toast){toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2800)}},420)}function escapeHtml(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}document.querySelectorAll('[data-open-chat]').forEach(b=>b.addEventListener('click',()=>openChat()));document.querySelectorAll('#suggestions button').forEach(b=>b.addEventListener('click',()=>respond(b.textContent)));document.querySelector('#closeChat').addEventListener('click',closeChat);backdrop.addEventListener('click',closeChat);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer.classList.contains('open'))closeChat()});document.querySelector('#chatForm').addEventListener('submit',e=>{e.preventDefault();const q=input.value;input.value='';respond(q)});
